async function cachedFetch(name, download) {
  const file = path.join(cacheDir, name);
  try {
    return await fs.readFile(file);
  } catch {
    const data = await download();
    await fs.mkdir(cacheDir, { recursive: true });
    await fs.writeFile(file, data);
    return data;
  }
}

