function highlight(text, indices) {
  let out = "", last = 0;
  for (const [s, e] of indices) {
    out += escapeHtml(text.slice(last, s)) + "<mark>" +
           escapeHtml(text.slice(s, e + 1)) + "</mark>";
    last = e + 1;
  }
  return out + escapeHtml(text.slice(last));
}

