from numba import guvectorize

@guvectorize(["void(float64[:], float64[:], float64[:])"], "(n),(n)->()")
def cosine_sim(a, b, out):
    dot = na = nb = 0.0
    for i in range(a.shape[0]):
        dot += a[i] * b[i]
        na += a[i] * a[i]
        nb += b[i] * b[i]
    out[0] = dot / (np.sqrt(na) * np.sqrt(nb))

cosine_sim(matrix, query)  # (m, n) against (n,) gives (m,)

