import pRetry from 'p-retry';

test('retries twice then succeeds', async () => {
  mock.timers.enable({ apis: ['setTimeout'] });
  let calls = 0;
  const promise = pRetry(async () => {
    if (++calls < 3) throw new Error('boom');
    return 'ok';
  }, { retries: 5, minTimeout: 1000 });

