from datetime import datetime, timedelta, timezone

def handle_datetimeoffset(value):
    tup = struct.unpack('<6hI2h', value)
    return datetime(
        tup[0], tup[1], tup[2], tup[3], tup[4], tup[5], tup[6] // 1000,
        timezone(timedelta(hours=tup[7], minutes=tup[8])),
    )

