function scale(hex) {
  const base = tinycolor(hex)
  const steps = [40, 30, 20, 10, 0, 10, 20, 30, 40]
  return steps.map((amount, i) =>
    (i < 4 ? base.clone().lighten(amount)
           : i === 4 ? base.clone()
           : base.clone().darken(amount)
    ).toHexString()
  )
}

