const { toObject, setViewport } = useReactFlow();

const save = () => {
  localStorage.setItem('flow', JSON.stringify(toObject()));
};

const restore = () => {
  const flow = JSON.parse(localStorage.getItem('flow'));
  if (!flow) return;
  setNodes(flow.nodes);
  setEdges(flow.edges);
  setViewport(flow.viewport);
};

